import {artworks} from './art.js';
import {artCards,artViewer,initArtViewer} from './art-gallery.js';
const projects=[
 {id:'police-n-thief',name:'Police N Thief',type:'Multiplayer party game',image:'police-n-thief.jpg',url:'https://police-n-thief.vercel.app/',intro:'A playful chase built around asymmetric roles, readable objectives and shared multiplayer moments.',focus:'Game rules · AI · Multiplayer · UI',description:'An independently developed police-and-thieves party-game prototype. Players pursue, steal and rescue through a set of readable roles, tools and multiplayer rules.',contribution:['Creative direction and gameplay rules','Player controls, AI behaviour and interface design','Online and local multiplayer, debugging and playable-build delivery'],design:'The design centres on a clear player relationship: one side pursues while the other steals and rescues. Distinct roles and tools create opportunities for cooperation, counterplay and changing situations.',tech:'The current local project uses Three.js for its browser renderer and includes a Steam desktop development workflow. The link here opens the public browser prototype.'},
 {id:'combat-patrol',name:'Combat Patrol',type:'Browser game',image:'combat-patrol.jpg',url:'https://combatpatrol.vercel.app/',intro:'A dark science-fiction browser game, presented through an atmospheric, focused interface.',focus:'Solo project · Browser playable',description:'A personal browser-game project with a dark science-fiction presentation. The public build offers a new-game flow, resume, settings and credits.',contribution:['Solo design and development','Public browser build available to explore'],design:'A focused title screen establishes the tone before play. This project extends my independent practice into a darker science-fiction setting.',tech:'A personal game-development project, playable directly in a web browser.'},
 {id:'potionpendium',name:'Potionpendium',type:'Potion puzzle',image:'potionpendium.jpg',url:'https://potionpendium.vercel.app/',intro:'A tactile potion puzzle with colourful gems, bottle queues and a little brewing strategy.',focus:'Puzzle systems · Interaction · Progression',description:'A browser puzzle built around a cauldron of potion gems and queues of bottles. The interface brings together brewing slots, mana abilities, mastery titles and daily or journey play.',contribution:['Solo design and development','Playable puzzle with bottle queues and gem interactions','Daily and journey modes, mana spells and mastery progression visible in the public build'],design:'Bottle capacities, blocked queues and a limited brewing shelf make the next move a planning decision. Mana abilities provide ways to respond when the board becomes difficult.',tech:'Open the browser build to try the current puzzle. The thumbnail is captured directly from its live interface.'},
 {id:'quantum-loom',name:'QuantumLoom',type:'Circuit puzzle',image:'quantum-loom.jpg',url:'https://quantum-loom.vercel.app/',intro:'A visual circuit puzzle connecting approachable strand routing with quantum-state exploration.',focus:'Systems design · Visual learning · Interaction',description:'A browser circuit puzzle with two entry points: a visual Loom Mode and a more advanced Quantum Mode using state vectors. Players work toward a target signature with a gate array.',contribution:['Solo design and development','Visual strand-routing mode and advanced quantum mode','Interactive circuit presentation, target states and gate controls visible in the public build'],design:'Two modes offer different levels of abstraction. Visual strands introduce routing relationships, while the advanced mode exposes state vectors for deeper exploration.',tech:'The thumbnail shows the visual Loom Mode. Visit the live build to choose either mode and explore the current experience.'}
];
const experience=[
 {company:'Todak Studios',roles:[
  {period:'2025–Present',title:'Producer / Project Manager',summary:'Coordinate multidisciplinary production involving 40–45 employees. Manage task visibility, resource allocation, milestone forecasting and delivery-risk escalation. Facilitate communication across technical, creative and stakeholder teams; support candidate reviews, voice auditions and structured QA playtests.',projects:[['Internal and external game projects','Production planning, milestone tracking, resource coordination and delivery.']]},
  {period:'Apr 2022–2024',title:'Creative Director',summary:'Established creative direction, art briefs and visual standards, aligning artists and designers through reviews, feedback and technical guidance.',projects:[['Mastra Battle Arena','Creative direction, visual identity, world-building, early gameplay design and individual hero mechanics.'],['Mastra Opening Trailer','Visual storytelling, shot composition, camera framing, cinematic pacing and editing choices.']]}
 ]},
 {company:'Virtuos Kuala Lumpur',roles:[{period:'Mar 2021–Apr 2022',title:'3D Artist',summary:'Produced 3D assets within commercial game co-development pipelines.',projects:[['Medal of Honor: Above and Beyond','3D asset production and optimization for VR production requirements.'],['CrossFire HD','Commercial game asset production.']]}]},
 {company:'Studio Kamii',roles:[{period:'Jan 2018–Mar 2021',title:'Technical Art Director',summary:'Worked with the Game Director and concept artists to bridge creative requirements and technical implementation.',projects:[['ToGather:Island','Technical art direction and 3D asset production. Released on Steam.'],['NevaLogik','Technical art and asset production.']]}]},
 {company:'Animonsta Studios',roles:[{period:'Oct 2014–Dec 2017',title:'3D Environment Artist',summary:'Created environment assets for feature-film and television animation production.',projects:[['BoBoiBoy: The Movie','Environment art, with VFX and compositing contributions.'],['BoBoiBoy Galaxy','3D environment assets for the television series.']]}]},
 {company:'Anifora Multimedia',roles:[{period:'2013–2014',title:'3D Animator',summary:'Character animation for educational television production.',projects:[['HadiHuda','3D animation for the educational series.']]}]},
 {company:'E-One Studio / Quark Energy System',roles:[{period:'2009–2013',title:'3D Artist',summary:'Created environment assets and animation for game production.',projects:[['Hoodwink','Environment asset creation and animation.']]}]},
 {company:'Les’ Copaque',roles:[{period:'2009',title:'Compositor',summary:'Compositing, colour correction and visual quality checking for animation production.',projects:[['Upin & Ipin','Colour correction and quality checking.']]}]}
];
const main=document.querySelector('main');
const button=(href,label,primary=false)=>`<a ${href.endsWith('.pdf')?'download':''} class="button ${primary?'primary':''}" href="${href}">${label}</a>`;
const external=(url,label)=>`<a class="button primary" href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>`;
const card=p=>`<a class="project-card" href="#/project/${p.id}"><div class="thumb"><img src="assets/${p.image}" alt="${p.name} live browser screenshot" loading="lazy"><span>${p.type}</span></div><div class="card-top"><h2>${p.name}</h2><span>View project</span></div><p>${p.intro}</p></a>`;
const heading=(label,title,text)=>`<div class="page-head">${label?'<span class="eyebrow">'+label+'</span>':''}<h1>${title}</h1><p>${text}</p></div>`;
const projectCredits=items=>'<ul class="project-credits">'+items.map(([title,credit])=>'<li><strong>'+title+'</strong> — '+credit+'</li>').join('')+'</ul>';
const roleDetails=roles=>roles.map(r=>'<section class="company-role"><time>'+r.period+'</time><h3>'+r.title+'</h3><p>'+r.summary+'</p>'+projectCredits(r.projects)+'</section>').join('');
const exp=()=>experience.map(c=>'<article class="experience company-experience"><h2>'+c.company+'</h2>'+roleDetails(c.roles)+'</article>').join('');
function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">Ahmad Fadzil / Creative leader & game maker</span><h1>Clear vision.<br><em>Playable</em><br><em>worlds.</em></h1><p>I connect creative direction, hands-on development and production leadership to bring games from an idea to a shared experience.</p><div class="actions">${button('#/work','Explore work',true)}${button('#/solo/games','Play solo projects')}</div></div><div class="scene-shell cube-shell" id="scene" role="region" aria-label="Playable Rubik’s cube"></div><span class="side-label">BASED IN MALAYSIA / OPEN TO GAME DIRECTOR ROLES</span></section>
 <div class="stats"><div class="stat"><strong>17+ years</strong><span>Games & animation experience</span></div><div class="stat"><strong>40–45</strong><span>Staff in coordinated studio production</span></div><div class="stat"><strong>Vision to play</strong><span>Creative, technical & production practice</span></div></div>
 <section class="section"><div class="section-heading"><div><span class="eyebrow">Independent development / Featured project</span><h2>Ideas made playable.</h2></div><a class="text-link" href="#/solo/games">Explore all solo projects</a></div><article class="featured"><a class="featured-image" href="#/project/police-n-thief"><img src="assets/police-n-thief.jpg" alt="Police N Thief colourful Three.js character and game menu"></a><div class="featured-copy"><div class="tags"><span class="tag">Solo development</span><span class="tag">Multiplayer</span><span class="tag">Three.js</span></div><h3>Police N Thief</h3><p>Asymmetric chase. Shared chaos. A party-game prototype built from gameplay rules and AI through to interface, multiplayer and playable delivery.</p>${button('#/project/police-n-thief','Explore the project')}</div></article></section>
 <section class="section"><div class="section-heading"><div><span class="eyebrow">Leadership in practice</span><h2>Direction with delivery.</h2></div><a class="text-link" href="#/cv">Read my experience</a></div><div class="leadership"><p>My career has moved from building worlds to shaping their creative direction and coordinating the teams that deliver them. I bring the perspective of an artist, a technical collaborator and a producer to game leadership.</p><div class="principles"><div><h3>Define a shared creative vision</h3><p>Art briefs, world-building and early hero gameplay concepts at Todak Studios.</p></div><div><h3>Connect creative and technical decisions</h3><p>Technical art direction at Studio Kamii and commercial co-development experience at Virtuos.</p></div><div><h3>Make the next milestone achievable</h3><p>Production planning, team alignment, resource visibility and structured playtesting.</p></div></div></div><div class="credit-line"><span>Todak Studios</span><span>Virtuos Kuala Lumpur</span><span>Studio Kamii</span><span>Animonsta</span></div></section>
 <section class="section cta"><div><span class="eyebrow">The next chapter</span><h2>Let’s build something<br>worth playing.</h2><p>I’m interested in Game Director opportunities where creative judgement, multidisciplinary collaboration and practical delivery matter.</p></div>${button('#/contact','Start a conversation',true)}</section>`;}
function work(){return heading('Professional work','Work & experience.','Selected contributions across studio leadership, game development and animation production.')+'<div class="page-content">'+experience.map(c=>'<article class="work-row company-work"><div><h2>'+c.company+'</h2></div><div>'+roleDetails(c.roles)+'</div></article>').join('')+'<div class="actions">'+button('https://www.artstation.com/z_e_a_l','Explore ArtStation',true)+button('#/cv','View full CV')+'</div></div>';}
function solo(section='art'){
 const games=section==='games';
 const tabs='<nav class="solo-sections" aria-label="Solo subsections"><a href="#/solo/art"'+(!games?' aria-current="page"':'')+'>Art <span>'+artworks.length+'</span></a><a href="#/solo/games"'+(games?' aria-current="page"':'')+'>Games <span>'+projects.length+'</span></a></nav>';
 const content=games?'<div class="solo-section-heading"><div><span class="eyebrow">Independent development</span><h2>Games</h2></div><p>Explore each project, then play its live browser build.</p></div><div class="grid">'+projects.map(card).join('')+'</div>':'<div class="solo-section-heading"><div><span class="eyebrow">Environments / Sculpting / Props</span><h2>Art</h2></div><p>3D studies and production artwork from my portfolio. Select an image to view it in full.</p></div><div class="art-grid">'+artCards()+'</div>'+artViewer();
 return heading('Art & independent development','Solo work.','Worlds, characters and playable ideas. Explore the art or step into a game.')+'<section class="page-content">'+tabs+content+'</section>';
}
function project(id){const p=projects.find(x=>x.id===id);if(!p)return missing();return `<article class="detail"><a class="breadcrumb" href="#/solo/games">All games</a><div class="detail-top"><div><span class="eyebrow">Solo project / ${p.type}</span><h1>${p.name}</h1><p>${p.intro}</p></div><div class="actions">${external(p.url,'Play in browser')}</div></div><img class="detail-image" src="assets/${p.image}" alt="${p.name} public playable build"><div class="detail-columns"><aside><h2>Project overview</h2><dl><dt>Ownership</dt><dd>Personal / independent project</dd><dt>Focus</dt><dd>${p.focus}</dd><dt>Access</dt><dd>Public browser playable</dd></dl>${external(p.url,'Open live project')}</aside><div><h2>The experience</h2><p>${p.description}</p><h3>Scope & contribution</h3><ul>${p.contribution.map(x=>`<li>${x}</li>`).join('')}</ul><h3>Design perspective</h3><p>${p.design}</p><h3>Build context</h3><p>${p.tech}</p></div></div></article>`;}
function cv(){return heading('','Ahmad Fadzil','Creative direction, game development and production leadership. Full name: Ahmad Fadzil Bin Ahmad Nasharuddin.')+`<section class="page-content cv-layout"><aside class="cv-aside"><h2>Vision. Craft.<br>Team delivery.</h2><p>17+ years of combined experience across games and animation, from technical art and commercial co-development to creative direction and studio production.</p>${button('assets/Ahmad-Fadzil-CV.pdf','Download CV · PDF',true)}<button class="button" id="print-cv">Print web CV</button><p><a href="mailto:ahmadfadzil22@gmail.com">ahmadfadzil22@gmail.com</a></p><p><strong>Areas of practice</strong><br>Creative direction · Gameplay concepts · Prototyping · Technical art · Art briefs · Production planning · Multidisciplinary coordination · Recruitment · QA playtesting</p><p><a class="text-link" href="https://www.artstation.com/z_e_a_l" target="_blank" rel="noopener noreferrer">ArtStation portfolio</a></p></aside><div>${exp()}<article class="experience"><span class="eyebrow">Independent practice</span><h2>Solo development & prototyping</h2><p>Police N Thief, Combat Patrol, Potionpendium and QuantumLoom are available in the solo-project gallery.</p><div class="actions" style="margin-top:20px">${button('#/solo/games','Explore solo projects')}</div></article></div></section>`;}
function contact(){return `<section class="contact"><span class="eyebrow">Contact / Based in Selangor, Malaysia</span><h1>A shared vision.<br>A new world.</h1><p>Let’s discuss Game Director opportunities, creative leadership and the games your team wants to bring to life.</p><a class="contact-email" href="mailto:ahmadfadzil22@gmail.com">ahmadfadzil22@gmail.com</a><div class="contact-links"><a class="text-link" href="https://www.artstation.com/z_e_a_l" target="_blank" rel="noopener noreferrer">ArtStation</a><a class="text-link" href="assets/Ahmad-Fadzil-CV.pdf" download>Download CV</a><a class="text-link" href="#/solo/games">Play my projects</a></div></section>`;}
function missing(){return `<section class="error"><span class="eyebrow">Page not found</span><h1>Let’s get back to the work.</h1>${button('#/','Return to overview',true)}</section>`;}
let cleanup;
async function render(){cleanup?.();cleanup=null;const parts=(location.hash.slice(1)||'/').split('/').filter(Boolean);const page=parts[0]||'home';main.innerHTML=({home,work,solo:()=>solo(parts[1]),cv,contact}[page]||(()=>page==='project'?project(parts[1]):missing()))();document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===(page==='project'?'solo':page))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=`${page==='home'?'Game Direction & Creative Leadership':page==='project'?(projects.find(p=>p.id===parts[1])?.name||'Project'):({work:'Work',solo:parts[1]==='games'?'Solo Games':'Solo Art',cv:'CV',contact:'Contact'}[page]||'Page not found')} — Ahmad Fadzil`;window.scrollTo(0,0);document.getElementById('print-cv')?.addEventListener('click',()=>window.print());if(page==='solo')cleanup=initArtViewer(main);if(page==='home'){try{const {createScene}=await import('./scene.js');if(document.getElementById('scene'))cleanup=createScene(document.getElementById('scene'));}catch(e){console.warn('3D scene unavailable',e);document.getElementById('motion')?.remove();}}}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});
window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true});});render();
